"use strict";let ServiceDepartmentsComponent=new function(){let mThis=this;this.title_prop='Service Departments';this.base_url=$('#__base_url').val();this.self=$('#_main_serviceDepartmentsComponent');this.btnNew=$('#_svd_btnNew');this.tblItems=$('#_svd_tblItem');this.col_titles={"Numero":"No.","Name":"Name","Description":"Description","Create User":"Create User","Create At":"Create At","Action":"Action"};this.trans_title=(title_prop='undefined')=>{return(mThis.col_titles[title_prop]||'undefined');}
this.setLanguage=()=>{if(LocaleManager.lang!==mThis.lang){for(let prop in mThis.col_titles){mThis.col_titles[prop]=LocaleManager.trans(prop,'service',LocaleManager.lang);}
mThis.lang=LocaleManager.lang;}}
this.init=()=>{mThis.btnNew.on('click',(e)=>{let op={onClose:(e)=>{if(e){mThis.displayServiceDepartments();}}};ServiceDepartmentsDialog.show(op);});mThis.tblItems.on('click','.btn_item_modify',function(e){let item_id=$(this).data("id");let op={id:item_id,onClose:(e)=>{if(e){mThis.displayServiceDepartments();}}};ServiceDepartmentsDialog.show(op);});mThis.tblItems.on('click','.btn_item_delete',function(e){let item_id=$(this).data("id");cv_interact.confirm(`Delete this department?`,{title:"Delete Department",context:"delete"},(yes)=>{if(yes){let p={"id":item_id};vsapi.call(`${main_view.base_url}/api/settings/delete-department`,p).then(res=>{if(res.status_code===200){mThis.displayServiceDepartments();}else cv_interact.error(res.error_message);});}});});}
this.displayServiceDepartments=(onFinish=null)=>{mThis.setLanguage();let p={};window.vsapi.call(`${mThis.base_url}/api/settings/departments`,p,'POST',null).then((result)=>{let data=[];if(result.status_code===200)data=result.data;if(mThis.table){mThis.tblItems.DataTable().clear().destroy();mThis.tblItems.empty();mThis.table=null;}
data=StringSanitizer.sanitizeObject(data,null);let cnt=1;let my_columns=[{title:mThis.trans_title("Numero"),data:()=>{return cnt;}},{data:(item,a,b)=>{return[`<div>${item.name}</div>`].join('');},title:mThis.trans_title('Name')},{title:mThis.trans_title('Description'),data:"description"},{title:mThis.trans_title('Create User'),data:"create_user"},{title:mThis.trans_title('Create At'),data:"created_at"},{title:mThis.trans_title('Action'),data:function(item,a,b){return[`<div class="form-inline">`,`<a href="javascript:void(0)" class="btn_item_modify" data-id="${item.id}"><i class="fa fa-edit"></i></a> &nbsp;`,`<a href="javascript:void(0);" data-id="${item.id}" class="btn_item_delete"><i class="fa-solid fa-trash-can text-danger"></i></a>`,`</div>`].join('');}}];if(!mThis.table)
mThis.table=mThis.tblItems.DataTable({searching:false,destroy:true,paging:true,ordering:false,retrieve:true,info:true,pageLength:10,bLengthChange:false,saveState:true,'processing':true,'language':{'loadingRecords':'&nbsp;','processing':'Loading...',"emptyTable":LocaleManager.trans('No data to display','datatable')},'data':data,'columns':my_columns,"createdRow":function(row,data,dataIndex){cnt++;let tr=$(row);tr.data('id',data.id);}});if(typeof onFinish==='function')onFinish();});};this.show=(options=null)=>{if(!options)options={};mThis.options=options;mThis.displayServiceDepartments(()=>{main_view.setTitle(mThis.title_prop);mThis.self.show().siblings().hide();});}}
let ServiceDepartmentsDialog=new function(){let mThis=this;this.self=$(`#_msl_dlgDepartment`);this.formUntil=new FormUntil({"itemName":"Service Departments","formId":'_svd_dlgDepartment',"instance":this,"apiSave":`${main_view.base_url}/api/settings/save-department`,"apiGet":`${main_view.base_url}/api/settings/department-info`,"modifyTitle":"Modify Department","createTitle":"New Department","identityProps":['id'],"form_data_props":['id'],"sanitize_excepts":[],'use_alert_error':true,'beforeShow':()=>{}});this.show=(options)=>{mThis.formUntil.show(options);}}
$(document).ready(function(){ServiceDepartmentsComponent.init();});